#!/usr/bin/env bash
#
# Generated-artifact drift guard.
#
# Two artifacts under ui/src are GENERATED by the desktop crate's
# tests and committed to the repo; they must never drift from their Rust source
# of truth:
#   - bindings.ts          — the tauri-specta TypeScript command surface;
#   - goldens/provenance.json — a real hybrid-search hit's start_line for the
#                            fixture corpus, which the reader's TS golden test
#                            reads (the one line value crossing Rust→TS).
#
# This regenerates both headlessly (no window, no webview, no dev server) by
# running only their two generating tests, then fails if the working tree changed. CI
# runs this to reject PRs whose generated artifacts weren't regenerated after a
# command-surface or chunker change.
#
# Usage: ./scripts/check-bindings.sh
set -euo pipefail

script_dir="$(cd "$(dirname "$0")" && pwd)"
repo_root="$(cd "$script_dir/.." && pwd)"

cd "$repo_root"

# Reuse one compiled library-test artifact, without running unrelated app tests.
# Exact filters keep provenance generation distinct from other search tests.
cargo test --locked --package mdreader-app --lib --quiet \
  tests::export_bindings_up_to_date -- --exact
cargo test --locked --package mdreader-app --lib --quiet \
  search::tests::search_over_a_real_corpus_returns_provenance_bearing_hits -- --exact

git diff --exit-code HEAD -- \
  ui/src/bindings.ts \
  ui/src/goldens/provenance.json
